function getTfActivity(n: number, id: string, skills: string[]): ActivitySpec {
  const pair = TF_SOCIALES[n] ?? TF_SOCIALES[1];
  const isTrue = Math.random() < 0.5;
  const stmt = isTrue ? pair.trueStmt : pair.falseStmt;
  const hint = isTrue ? pair.trueHint : pair.falseHint;
  return makeTrueFalse(id, stmt, isTrue, hint, skills);
}

